/**
 * Every part name the schema declares, typed or not.
 *
 * A part is a child element, never an object: `<caption>`, `<imageSettings>`,
 * `<threshold>` and `<innerPolygon>` are parts of the object around them. A
 * renderer that tells objects from parts by a hand-kept list of names ends up
 * drawing a `<caption>` as a box of its own — measured on a real export, where
 * 19 objects became 41 drawn shapes and every caption was reported as an
 * unknown element. This list is the schema's answer, so the set cannot drift.
 */
export const PART_NAMES: readonly string[] = ['animateColor', 'animateFill', 'animateHeight', 'animateHorizontalPosition', 'animateHorizontalSlider', 'animateHyperlink', 'animateRotation', 'animateTouch', 'animateVerticalPosition', 'animateVerticalSlider', 'animateVisibility', 'animateWidth', 'animations', 'caption', 'color', 'connection', 'connections', 'constantExpressionRange', 'data', 'defaultExpressionRange', 'imageSettings', 'innerPolygon', 'parameter', 'parameters', 'property', 'readFromTagExpressionRange', 'rotation', 'state', 'states', 'threshold', 'transform']

/** The facts for one element, or `undefined` when the schema does not name it. */
export function elementFacts(name: string): NodeFacts | undefined {
  return Object.hasOwn(ELEMENTS, name) ? ELEMENTS[name] : undefined
}

/** The facts for one part, or `undefined` when it is read generically. */
export function partFacts(name: string): NodeFacts | undefined {
  return Object.hasOwn(PARTS, name) ? PARTS[name] : undefined
}

/** Whether the schema declares one attribute on a node. */
export function declaresAttribute(node: string, attribute: string): boolean {
  const facts = elementFacts(node) ?? partFacts(node)
  return facts !== undefined && facts.attributes.includes(attribute)
}
